    ("n022", False, "写出「佇む」的平假名读音。", ("たたずむ",), "难读汉字·停驻姿态·母语者", "在一处静静地站着。", "", "辞典释义（デジタル大辞泉）：佇む读たたずむ，表示站在某处停留不动。"),
    ("n023", False, "写出「恙ない」的平假名读音。", ("つつがない",), "难读汉字·平安状态·母语者", "没有疾病或意外，平安无事。", "", "辞典释义（デジタル大辞泉）：恙ない读つつがない，表示没有灾病、平安无事。"),
